INSERT INTO public.ai_prompt_rules VALUES ('a20f1bea-b3f8-4ee2-be1f-f65f12583bea', 'Fuhrpark-Nachrichten Zusammenfassung', 'Analysiere die folgenden Nachrichtenartikel für die Fuhrparkbranche. Fasse die 3 wichtigsten Nachrichten zusammen, die für einen Flottenmanager am relevantesten sind. Erkläre kurz, warum sie relevant sind. Nenne am Ende die originalen Links. Antworte prägnant in deutscher Sprache. Nachrichtenartikel: {{news_texts}}<!--PROMPT_PART_SEPARATOR-->sfsf<!--PROMPT_PART_SEPARATOR-->', 'Fasst aktuelle Fuhrpark-Nachrichten zusammen und hebt Relevantes hervor.', NULL, '2025-06-19 19:46:26.940124+02', '2025-07-22 20:45:25.270724+02', 'Google Gemini', false, NULL, 'text', '{}', '', '0 9 * * 1', true);
