INSERT INTO public.scraped_content VALUES ('9f7012d7-358b-4811-b1cf-28f160605460', 'bmw_news', 'https://www.press.bmwgroup.com/austria/article/detail/T0450798DE?language=de', 'BMW und Alvaro Barrington feiern Wasserstoffmobilität  auf der Art Basel in Basel 2025.  Anlässlich von 50 Jahren BMW Art Cars verwandelt der Künstler die BMW iX5 Hydrogen Flotte in ein mobiles Ausdrucksmittel für Kreativität und zukunftsweisende Innovation.', 'Im Jahr 2025 feiert BMW 50 Jahre BMW Art Cars. Um dieses Erbe mit der Gegenwart zu verbinden, haben der ehemalige Art Car Juror Hans Ulrich Obrist und BMW den renommierten Künstler Alvaro Barrington eingeladen, die BMW Hydrogen VIP-Fahrzeugflotte während der Art Basel in Basel 2025 in ein mobiles Kunstwerk zu verwandeln. Dies ist das zweite Jahr in Folge, in dem die BMW iX5 Hydrogen Flotte auf der Kunstmesse im Einsatz ist.', NULL, '2025-06-16', NULL, 'product_news', 0, '2025-07-18 14:30:29.34952+02', '2025-07-18 14:30:29.34952+02', '2025-07-18 14:30:29.34952+02', NULL, NULL, false);
