INSERT INTO public.scraped_content VALUES ('7c44d681-fb25-486a-909c-ebc5134a6aef', 'bmw_news', 'https://www.press.bmwgroup.com/austria/article/detail/T0451485DE?language=de', 'My BMW App zeigt Fahrern erstmals CO2-Emissionen über den gesamten Lebenszyklus.', '+++ BMW Group erweitert My Trips-Fahrstatistiken mit Update der My BMW und MINI App +++ Individueller CO2-Fußabdruck basiert auf Vehicle Footprint des Fahrzeugs sowie persönlich gefahrenen Strecken +++ Verfügbar für ausgewählte Modelle aller Antriebsarten +++', NULL, '2025-07-21', NULL, 'vehicle-product_news', 0, '2025-07-22 11:10:02.096742+02', '2025-07-22 11:10:02.096742+02', '2025-07-22 11:10:02.096742+02', 'Österreich', NULL, false);
INSERT INTO public.scraped_content VALUES ('bed4e3df-7294-4d10-b468-042330dba1a7', '606ed5c8-25b9-4b36-9436-0f0cfd7a5bfd_news', 'https://www.fuhrparkverband.at/stellungnahme-des-fuhrparkverbandes-austria-oeffentliche-konsultation-dekarbonisierung-der-unternehmensflotten-greening-corporate-fleets/', 'Stellungnahme des Fuhrparkverbandes Austria/Öffentliche Konsultation – Dekarbonisierung der Unternehmensflotten („Greening corporate fleets“)', 'Die EU-Kommission will bis Ende 2025 eine Gesetzesinitiative vorlegen, um die Umstellung auf emissionsfreie Fahrzeuge bei Unternehmensflotten zu beschleunigen. Stellungnahme des Fuhrparkverbandes Austria Der FVA erachtet die Dekarbonisierung und die Reduktion der Treibhausgase als eine wichtige Aufgabe und unterstützt daher diesbezügliche Initiativen. Zur Erreichung der Ziele sieht der FVA allerdings…', NULL, '2025-07-03', NULL, 'businesspartner_news', 1, '2025-07-10 18:29:58.970114+02', '2025-07-10 18:29:58.970114+02', '2025-07-10 18:29:58.970114+02', 'Österreich', NULL, false);
